    fun obtenerRegiones(): List<String> = regiones.map { it.nombre }

    fun obtenerComunas(region: String, filtro: String): List<String> {
        val encontrada = regiones.firstOrNull { it.nombre == region } ?: return emptyList()
        if (filtro.isBlank()) return encontrada.comunas
        return encontrada.comunas.filter { it.startsWith(filtro.trim(), ignoreCase = true) }
    }
